select disposition_return(r.return_id, 'good', 'restocked') from returns r join orders o using(order_id) where o.external_order_id='AMAZ-1119';
select disposition_return(r.return_id, 'good', 'restocked') from returns r join orders o using(order_id) where o.external_order_id='SHOP-1119';
