-- claims across every lifecycle state, advanced through the real state machine
insert into claims (order_id, claim_type, potential_amount, deadline, owner, status)
select o.order_id, v.ct, case when v.ct in ('incorrect_deduction','excess_deduction') then round(o.net_amount*.08,2) else o.net_amount end, v.dl::date, 'f08a6962-1e79-4a95-85a8-e59910ebdaff', 'potential' from (values
('SHOP-1132','lost_shipment','2026-10-03'),
('AMAZ-1118','lost_shipment','2026-10-10'),
('FLIP-1114','damaged_return','2026-10-29'),
('SHOP-1106','other','2026-10-06'),
('AMAZ-1110','incorrect_deduction','2026-10-19'),
('FLIP-1118','excess_deduction','2026-10-26')
) as v(ext,ct,dl) join orders o on o.external_order_id=v.ext;
select advance_claim(c.claim_id,'claimed') from claims c join orders o using(order_id) where o.external_order_id='AMAZ-1118' and c.claim_type='lost_shipment';
select advance_claim(c.claim_id,'claimed') from claims c join orders o using(order_id) where o.external_order_id='FLIP-1114' and c.claim_type='damaged_return';
select advance_claim(c.claim_id,'approved') from claims c join orders o using(order_id) where o.external_order_id='FLIP-1114' and c.claim_type='damaged_return';
select advance_claim(c.claim_id,'claimed') from claims c join orders o using(order_id) where o.external_order_id='SHOP-1106' and c.claim_type='other';
select advance_claim(c.claim_id,'rejected') from claims c join orders o using(order_id) where o.external_order_id='SHOP-1106' and c.claim_type='other';
select advance_claim(c.claim_id,'claimed') from claims c join orders o using(order_id) where o.external_order_id='AMAZ-1110' and c.claim_type='incorrect_deduction';
select advance_claim(c.claim_id,'approved') from claims c join orders o using(order_id) where o.external_order_id='AMAZ-1110' and c.claim_type='incorrect_deduction';
select advance_claim(c.claim_id,'recovered', c.approved_amount) from claims c join orders o using(order_id) where o.external_order_id='AMAZ-1110' and c.claim_type='incorrect_deduction';
select advance_claim(c.claim_id,'claimed') from claims c join orders o using(order_id) where o.external_order_id='FLIP-1118' and c.claim_type='excess_deduction';
select advance_claim(c.claim_id,'approved') from claims c join orders o using(order_id) where o.external_order_id='FLIP-1118' and c.claim_type='excess_deduction';